import subprocess
result = subprocess.run(['pdftotext', 'main.pdf', '-'], capture_output=True, text=True)
text = result.stdout
pages = text.split('\x0c')
total = len([p for p in pages if p.strip()])
print(f'Total pages: {total}')

for i, page in enumerate(pages, 1):
    if not page.strip():
        continue
    if 'Limitations' in page and i < 10:
        lines = page.strip().split('\n')
        for j, l in enumerate(lines):
            if l.strip() == 'Limitations':
                print(f'Limitations starts: page {i}')
                break
    if 'References' in page and i < 10:
        lines = page.strip().split('\n')
        for j, l in enumerate(lines):
            if l.strip() == 'References':
                print(f'References starts: page {i}')
                break
